+      expect(terminalHostManager.getInstance("sess-overlap-destroy")).toBeUndefined();
+      expect(mocks.terminalDisposed).toHaveBeenCalled();
+
+      // 5. Resolve second (legitimate) creation
+      deferredPrefs2.resolve(terminalSettings.FALLBACK_PREFERENCES);
+      const newInstance = await secondCreation;
+
+      expect(newInstance).toBeDefined();
+      expect(newInstance).not.toBe(staleInstance);
+      expect(terminalHostManager.getInstance("sess-overlap-destroy")).toBe(newInstance);
+    } finally {
+      prefsSpy.mockRestore();
+      terminalHostManager.destroy("sess-overlap-destroy");
+    }
+  });
+
+  it("evicts oldest inactive instance when exceeding warm budget while preserving all visible split instances and backend sessions", async () => {
+    // Warm capacity = 2 inactive instances
+    terminalHostManager.setWarmCacheLimit(2);
+
+    // 1. Two visible split instances
+    const visSession1 = createSession("sess-vis-1", "backend-vis-1");
+    const visSession2 = createSession("sess-vis-2", "backend-vis-2");
+
+    const unregVis1 = terminalHostManager.registerVisible("sess-vis-1");
+    const unregVis2 = terminalHostManager.registerVisible("sess-vis-2");
+
+    await terminalHostManager.getOrCreate(visSession1, true);
+    await terminalHostManager.getOrCreate(visSession2, false);
+
+    expect(terminalHostManager.getInstance("sess-vis-1")).toBeDefined();
+    expect(terminalHostManager.getInstance("sess-vis-2")).toBeDefined();
+
+    // 2. Add 3 inactive sessions in sequence (exceeding warm budget of 2)
+    const inact1 = createSession("sess-inact-1", "backend-inact-1");
+    const inact2 = createSession("sess-inact-2", "backend-inact-2");
+    const inact3 = createSession("sess-inact-3", "backend-inact-3");
+
+    await terminalHostManager.getOrCreate(inact1, false);
+    await terminalHostManager.getOrCreate(inact2, false);
+    await terminalHostManager.getOrCreate(inact3, false);
+
+    // 3. Oldest inactive frontend renderer must be disposed and evicted
+    expect(terminalHostManager.getInstance("sess-inact-1")).toBeUndefined();
+    expect(mocks.terminalDisposed).toHaveBeenCalled();
+
+    // 4. Visible split instances MUST remain pinned and not evicted
+    expect(terminalHostManager.getInstance("sess-vis-1")).toBeDefined();
+    expect(terminalHostManager.getInstance("sess-vis-2")).toBeDefined();
+
+    // 5. Inactive instances within warm budget (2 and 3) remain warm
+    expect(terminalHostManager.getInstance("sess-inact-2")).toBeDefined();
+    expect(terminalHostManager.getInstance("sess-inact-3")).toBeDefined();
+
+    // 6. Backend session record for inact1 is NOT closed or destroyed
+    expect(inact1.backendSessionId).toBe("backend-inact-1");
+
+    unregVis1();
+    unregVis2();
+    terminalHostManager.destroy("sess-vis-1");
+    terminalHostManager.destroy("sess-vis-2");
+    terminalHostManager.destroy("sess-inact-2");
+    terminalHostManager.destroy("sess-inact-3");
+  });
+
+  it("suspends inactive output without background writes and replays in correct order upon reactivation", async () => {
+    const session = createSession("sess-suspend", "backend-suspend");
+    const unreg = terminalHostManager.registerVisible("sess-suspend");
+    await terminalHostManager.getOrCreate(session, true);
+
+    // Initial output while visible
+    mocks.terminalWrites.length = 0;
+    mocks.emitSessionOutput("backend-suspend", "vis-1");
+    flushAnimationFrames();
+    expect(mocks.terminalWrites).toEqual(["vis-1"]);
+
+    // Unmount / suspend session
+    unreg();
+
+    // Clear write logs
+    mocks.terminalWrites.length = 0;
+
+    // Output emitted while inactive: TerminalEventBus processes it, but xterm does NOT write
+    const backlogChunks = ["vis-1"];
+    vi.spyOn(terminalEventBus, "subscribeOutput").mockImplementation((sessionId: string, cb: (text: string) => void) => {
+      let set = mocks.outputListeners.get(sessionId);
+      if (!set) {
+        set = new Set();
+        mocks.outputListeners.set(sessionId, set);
+      }
+      set.add(cb);
+      // Replay full backlog
+      cb(backlogChunks.join(""));
+      return vi.fn(() => {
+        set?.delete(cb);
+        if (set?.size === 0) mocks.outputListeners.delete(sessionId);
+      });
+    });
+
+    mocks.emitSessionOutput("backend-suspend", "inact-2");
+    backlogChunks.push("inact-2");
+    flushAnimationFrames();
+
+    // No direct background writes while suspended
+    expect(mocks.terminalWrites).toHaveLength(0);
+
+    // Reactivate session
+    const unreg2 = terminalHostManager.registerVisible("sess-suspend");
+    await terminalHostManager.getOrCreate(session, true);
+
+    // Terminal must be reset before replaying backlog so stale output is not duplicated
+    expect(mocks.terminalReset).toHaveBeenCalled();
+
+    flushAnimationFrames();
+    // Replay delivers complete backlog in order
+    expect(mocks.terminalWrites).toContain("vis-1inact-2");
+
+    unreg2();
+    terminalHostManager.destroy("sess-suspend");
+  });
+
+  it("synchronously flushes pending output when accumulated characters reach or exceed MAX_PENDING_OUTPUT_CHARS before rAF", async () => {
+    const session = createSession("sess-cap", "backend-cap");
+    const unreg = terminalHostManager.registerVisible("sess-cap");
+    await terminalHostManager.getOrCreate(session, true);
+
+    mocks.terminalWrites.length = 0;
+
+    const halfCap = "A".repeat(MAX_PENDING_OUTPUT_CHARS / 2);
+    const exceedCap = "B".repeat(MAX_PENDING_OUTPUT_CHARS / 2 + 10);
+    const trailingChunk = "C".repeat(50);
+
+    // 1. Below cap: queued without immediate write
+    mocks.emitSessionOutput("backend-cap", halfCap);
+    expect(mocks.terminalWrites).toHaveLength(0);
+
+    // 2. Reaching/exceeding cap: synchronously flushes accumulated batch immediately before rAF
+    mocks.emitSessionOutput("backend-cap", exceedCap);
+    expect(mocks.terminalWrites).toEqual([halfCap + exceedCap]);
+
+    // 3. New chunk arriving after flush is held for next rAF
+    mocks.emitSessionOutput("backend-cap", trailingChunk);
+    expect(mocks.terminalWrites).toEqual([halfCap + exceedCap]);
+
+    // 4. On rAF flush, trailing chunk is written in ordered sequence
+    flushAnimationFrames();
+    expect(mocks.terminalWrites).toEqual([halfCap + exceedCap, trailingChunk]);
+
+    unreg();
+    terminalHostManager.destroy("sess-cap");
+  });
+
+  it("supports 100 simulated live sessions across five workspaces with visible sessions pinned and inactive renderers bounded by warm limit", async () => {
+    const originalLimit = terminalHostManager.getWarmCacheLimit();
+    const targetWarmLimit = 3;
+    terminalHostManager.setWarmCacheLimit(targetWarmLimit);
+    expect(terminalHostManager.getWarmCacheLimit()).toBe(targetWarmLimit);
+
+    const closeTerminalSpy = vi.spyOn(tauriApi, "closeTerminal");
+    const spawnTerminalSpy = vi.spyOn(tauriApi, "spawnTerminal");
+
+    const totalWorkspaces = 5;
+    const sessionsPerWorkspace = 20;
+    const allSessions: TerminalSession[] = [];
+
+    for (let wsIndex = 0; wsIndex < totalWorkspaces; wsIndex++) {
+      const wsId = `ws-${wsIndex}`;
+      for (let sIndex = 0; sIndex < sessionsPerWorkspace; sIndex++) {
+        const id = `${wsId}-sess-${sIndex}`;
+        allSessions.push(createSession(id, `backend-${id}`, wsId));
+      }
+    }
+    expect(allSessions).toHaveLength(100);
+
+    // Explicit visible set across multiple workspaces (one visible per workspace)
+    const visibleSessionIds = [
+      "ws-0-sess-0",
+      "ws-1-sess-4",
+      "ws-2-sess-8",
+      "ws-3-sess-12",
+      "ws-4-sess-16",
+    ];
+
+    const unregHandles = new Map<string, () => void>();
+    for (const visId of visibleSessionIds) {
+      unregHandles.set(visId, terminalHostManager.registerVisible(visId));
+    }
+
+    // Register a second visible mount for one session to verify reference-count behavior
+    const multiRefSessionId = visibleSessionIds[0]!;
+    const unregSecondMount = terminalHostManager.registerVisible(multiRefSessionId);
+
+    try {
+      // Create all 100 sessions sequentially
+      for (const session of allSessions) {
+        const isVisible = terminalHostManager.isSessionVisible(session.id);
+        await terminalHostManager.getOrCreate(session, isVisible);
+      }
+
+      // 1. Visible renderer instances remain pinned and alive
+      for (const visId of visibleSessionIds) {
+        expect(terminalHostManager.isSessionVisible(visId)).toBe(true);
+        const inst = terminalHostManager.getInstance(visId);
+        expect(inst).toBeDefined();
+        expect(inst?.session.id).toBe(visId);
+      }
+
+      // 2. Count alive instances: visible vs inactive
+      const aliveInstances = allSessions.filter((s) => terminalHostManager.getInstance(s.id) !== undefined);
+      const aliveVisible = aliveInstances.filter((s) => terminalHostManager.isSessionVisible(s.id));
+      const aliveInactive = aliveInstances.filter((s) => !terminalHostManager.isSessionVisible(s.id));
+
+      expect(aliveVisible).toHaveLength(visibleSessionIds.length);
+      expect(aliveInactive.length).toBeLessThanOrEqual(terminalHostManager.getWarmCacheLimit());
+      expect(aliveInactive.length).toBe(targetWarmLimit);
+      expect(aliveInstances).toHaveLength(visibleSessionIds.length + targetWarmLimit);
+
+      // 3. All 100 backendSessionId values and session objects remain intact
+      for (const session of allSessions) {
+        expect(session.backendSessionId).toBe(`backend-${session.id}`);
+        expect(session.lifecycle).toBe("working");
+        expect(session.workspaceId).toMatch(/^ws-\d+$/);
+      }
+
+      // 4. No backend close, spawn, or IPC APIs were called by frontend manager eviction
+      expect(closeTerminalSpy).not.toHaveBeenCalled();
+      expect(spawnTerminalSpy).not.toHaveBeenCalled();
+
+      // 5. Oldest inactive frontend renderers were disposed
+      const allInactiveSessions = allSessions.filter((s) => !visibleSessionIds.includes(s.id));
+      const expectedWarmInactive = allInactiveSessions.slice(-targetWarmLimit);
+      const expectedDisposedInactive = allInactiveSessions.slice(0, -targetWarmLimit);
+
+      expect(expectedDisposedInactive.length).toBe(95 - targetWarmLimit);
+      for (const session of expectedDisposedInactive) {
+        expect(terminalHostManager.getInstance(session.id)).toBeUndefined();
+      }
+      for (const session of expectedWarmInactive) {
+        expect(terminalHostManager.getInstance(session.id)).toBeDefined();
+      }
+
+      // 6. Verify reference-count behavior:
+      // Release first mount handle of multiRefSessionId
+      const unregFirstMount = unregHandles.get(multiRefSessionId)!;
+      unregFirstMount();
+
+      // Proving it remains pinned until the final handle releases
+      expect(terminalHostManager.isSessionVisible(multiRefSessionId)).toBe(true);
+      expect(terminalHostManager.getInstance(multiRefSessionId)).toBeDefined();
+
+      // Release the second (final) mount handle
+      unregSecondMount();
+      expect(terminalHostManager.isSessionVisible(multiRefSessionId)).toBe(false);
+
+      // Now multiRefSessionId transitioned to inactive and joined warm LRU cache
+      const inactiveAfterRelease = allSessions.filter(
+        (s) => !terminalHostManager.isSessionVisible(s.id) && terminalHostManager.getInstance(s.id) !== undefined,
+      );
+      expect(inactiveAfterRelease.length).toBeLessThanOrEqual(terminalHostManager.getWarmCacheLimit());
+    } finally {
+      for (const unreg of unregHandles.values()) {
+        unreg();
+      }
+      for (const session of allSessions) {
+        terminalHostManager.destroy(session.id);
+      }
+      terminalHostManager.setWarmCacheLimit(originalLimit);
+      closeTerminalSpy.mockRestore();
+      spawnTerminalSpy.mockRestore();
+    }
+  });
 });

