import sys

def count_pure_lines(filepath):
    with open(filepath, "r", encoding="utf-8") as f:
        lines = f.readlines()

    pure_count = 0
    in_block_comment = False
    for line in lines:
        stripped = line.strip()
        if not stripped:
            continue
        if in_block_comment:
            if "*/" in stripped:
                in_block_comment = False
                # check if there is code after */
                after = stripped.split("*/", 1)[1].strip()
                if after and not after.startswith("//"):
                    pure_count += 1
            continue
        if stripped.startswith("/*"):
            if "*/" in stripped:
                after = stripped.split("*/", 1)[1].strip()
                if after and not after.startswith("//"):
                    pure_count += 1
            else:
                in_block_comment = True
            continue
        if stripped.startswith("//"):
            continue
        pure_count += 1
    return pure_count, len(lines)

